{
  "passageId": "fear-appeal-persuasion",
  "items": [
    {
      "id": "R1",
      "type": "BACKGROUND",
      "otherName": "",
      "reason": "기존 연구에서 설득 효과를 다루지 않았다는 사정이 재니스가 해당 효과에 주목한 연구 배경이므로 배경·계기 관계이다."
    },
    {
      "id": "R2",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "세 수준으로 나누어 실시한 실험 결과가 중간 수준의 설득 효과가 가장 크다는 결론의 근거이다."
    },
    {
      "id": "R3",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "레벤달이 재니스의 연구를 감정적 측면에 편중되었다고 명시적으로 문제 삼으므로 비판·반박 관계이다."
    },
    {
      "id": "R4",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "감정적 측면에 치우쳤다는 연구의 한계에 대응하여 인지적 반응까지 포함하는 보완 설명을 제시한다."
    },
    {
      "id": "R5",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "설득 효과와 관련된 감정적 반응에 ‘공포 통제 반응’이라는 이름을 붙이는 관계이다."
    },
    {
      "id": "R6",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "설득 효과와 관련된 인지적 반응에 ‘위험 통제 반응’이라는 이름을 붙이는 관계이다."
    },
    {
      "id": "R7",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "서로 다른 학자의 견해가 아니라 두 반응을 위험 무시와 권고 이행이라는 수용자 행동의 차이로 대조한다."
    },
    {
      "id": "R8",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "위티가 앞선 연구들을 수용하고 종합하여 자신의 이론으로 이어받는 관계이다."
    },
    {
      "id": "R9",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "두 요인을 설정했다는 개괄적 설명에서 그중 위협의 수준이 높다는 것이 어떤 경우인지 구체적으로 풀어 준다."
    },
    {
      "id": "R10",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "두 요인을 설정했다는 개괄적 설명에서 그중 효능감의 수준이 높다는 것이 어떤 경우인지 구체적으로 풀어 준다."
    },
    {
      "id": "R11",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "위협 수준에 관한 일반 원리를 동호회 회원 자격 상실이라는 구체적 사례에 가져다 적용한다."
    },
    {
      "id": "R12",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "효능감 수준에 관한 일반 원리를 동호회 모임 참석 권고라는 구체적 사례에 가져다 적용한다."
    },
    {
      "id": "R13",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "불참하면 회원 자격을 잃는다는 안내문의 내용이 애착이 강한 회원에게 높은 위협이라는 판단을 뒷받침한다."
    },
    {
      "id": "R14",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "모임 참석이라는 동일한 권고를 수용자가 이행하기 쉽다고 느끼는 경우와 그때의 효능감으로 자세히 설명한다."
    },
    {
      "id": "R15",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "위협과 효능감의 개별 의미를 설명하던 논의가 두 요인과 통제 반응을 연결하는 단계로 확장된다."
    },
    {
      "id": "R16",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "위티가 레벤달의 두 통제 반응 구분을 받아들여 자신의 결론을 구성하므로 이론 간 수용 관계이다."
    },
    {
      "id": "R17",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "두 요인과 통제 반응을 연결해 결론을 도출했다는 설명을 실제 결론의 내용으로 구체화한다."
    },
    {
      "id": "R18",
      "type": "CONDITION",
      "otherName": "",
      "reason": "위협이 높은 상황에서 효능감의 높고 낮음이라는 조건에 따라 작동하는 통제 반응이 갈린다."
    },
    {
      "id": "R19",
      "type": "CONDITION",
      "otherName": "",
      "reason": "위협 수준에 따라 효능감에 따른 통제 반응이 나타나는 경우와 아예 반응하지 않는 경우로 나뉜다."
    },
    {
      "id": "R20",
      "type": "CAUSE",
      "otherName": "",
      "reason": "위협이 자신에게 영향을 주지 않는다는 수용자의 인식이 공포 소구에 반응하지 않는 결과로 이어지는 실제 심리적 작용이다."
    },
    {
      "id": "R21",
      "type": "CAUSE",
      "otherName": "",
      "reason": "높은 위협과 높은 효능감이 위험 통제 반응을 작동시키고 그 반응이 권고 이행으로 이어지는 실제 작용을 연결한다."
    },
    {
      "id": "R22",
      "type": "CAUSE",
      "otherName": "",
      "reason": "높은 위협과 낮은 효능감이 공포 통제 반응을 작동시키고 그 반응이 위험 무시로 이어지는 실제 작용을 연결한다."
    },
    {
      "id": "R23",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "기존 공포 소구 이론을 통합했다는 사실이 후속 연구의 중요한 디딤돌이라는 의의 판단의 근거이다."
    }
  ]
}

